CREATE TABLE "vehicles" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "make" TEXT NOT NULL, "model" TEXT NOT NULL, "year" INTEGER NOT NULL, "license_plate" TEXT NULL, "photo_path" TEXT NULL, "current_mileage" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "service_records" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "vehicle_id" INTEGER NOT NULL REFERENCES vehicles (id) ON DELETE CASCADE, "title" TEXT NOT NULL, "description" TEXT NULL, "service_date" INTEGER NOT NULL, "mileage" INTEGER NULL, "cost" REAL NULL, "service_type" TEXT NOT NULL DEFAULT 'OTHER', "workshop" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "attachments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "service_record_id" INTEGER NOT NULL REFERENCES service_records (id) ON DELETE CASCADE, "file_path" TEXT NOT NULL, "file_type" TEXT NOT NULL, "file_name" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "reminders" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "vehicle_id" INTEGER NOT NULL REFERENCES vehicles (id) ON DELETE CASCADE, "title" TEXT NOT NULL, "note" TEXT NULL, "due_date" INTEGER NULL, "due_mileage" INTEGER NULL, "is_done" INTEGER NOT NULL DEFAULT 0 CHECK ("is_done" IN (0, 1)), "service_type" TEXT NOT NULL DEFAULT 'OTHER', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
